/** The live socket's URL: `path` on the client's base URL, as `ws:` or `wss:`. */
export function liveUrl(baseUrl: string, path: string): string {
  const origin = baseUrl || (typeof location === "undefined" ? "http://localhost" : location.origin);
  const url = new URL(path, origin);
  url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
  return url.toString();
}

/** A `subscribe` frame: the topic, the filter and `echo` only when there is one — or an `open` frame for a stream query. */
function subscribeFrame(sub: string, entry: LiveEntry): Record<string, unknown> {
  if (entry.query !== undefined) {
    const open: Record<string, unknown> = { type: "open", sub, query: entry.query.name, params: entry.query.params };
    if (entry.handlers.echo) open["echo"] = true;
    return open;
  }
  const frame: Record<string, unknown> = { type: "subscribe", sub, stream: entry.stream };
  if (entry.topic !== undefined) frame["topic"] = entry.topic;
  if (entry.filter !== undefined) frame["filter"] = entry.filter;
  if (entry.handlers.echo) frame["echo"] = true;
  return frame;
}

type LiveEntry = {
  stream: string;
  topic: string | undefined;
  filter: Record<string, unknown> | undefined;
  handlers: LiveHandlers<unknown>;
  ready: boolean;
  canPublish: boolean;
  /** Who is on the topic, on a stream with presence. */
  members: LiveMember[];
  /** This connection's id, from the last `presence` frame. */
  me: string | undefined;
  /** The page's presence state, kept to send again after a reconnect. */
  state: { value: unknown } | undefined;
  /** When the state was last sent, and the timer holding a newer one back. */
  stateSentAt: number;
  stateTimer: ReturnType<typeof setTimeout> | undefined;
  /** Publishes made before `ready`, sent once it arrives. */
  outbox: unknown[];
  /** On a document stream: whether the last `doc_sync` said read-only. */
  readOnly: boolean;
  /** For a stream query: its name and parameters, sent again after a reconnect. */
  query: { name: string; params: Record<string, unknown> } | undefined;
  /** For a stream query: what `ready` said it opened. */
  opened: LiveOpened | undefined;
};

/** One socket, any number of subscriptions, reconnecting by itself. */
export class LiveConnection {
  private socket: WebSocket | undefined;
  private readonly entries = new Map<string, LiveEntry>();
  private readonly listeners = new Set<(status: LiveStatus) => void>();
  private nextSub = 1;
  private attempt = 0;
  private opened = false;
  private timer: ReturnType<typeof setTimeout> | undefined;
  private current: LiveStatus = "connecting";
  // Fields assigned in the body rather than as parameter properties: Node runs
  // this file by stripping its types, and a parameter property is not erasable.
  private readonly url: string;
  private readonly options: LiveOptions;

  constructor(url: string, options: LiveOptions = {}) {
    this.url = url;
    this.options = options;
  }

  /** Where the connection is now. */
  get status(): LiveStatus {
    return this.current;
  }

  /** Be told when the status changes. Returns the function that stops it. */
  onStatus(listener: (status: LiveStatus) => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * The accessor for the stream called `name` — one with no topic, or whose
   * topic is the subscriber's own. It can join and publish too; the generated
   * client's types offer those only on a stream whose settings allow them.
   */
  stream<E>(name: string): LiveStream<E> & LivePresence<E> & LivePublish<E> {
    return {
      name,
      connection: this,
      subscribe: (handlers: LiveHandlers<E>) => this.subscribe(name, handlers),
      join: (handlers: LiveJoinHandlers<E> = {}) => this.join<E>(name, undefined, handlers),
      publish: (value: LiveValue<E>) => this.publishOn(name, undefined, value),
    };
  }

  /** The accessor for the stream called `name`, whose topics are rows. */
  rowStream<E>(name: string): LiveRowStream<E> & LiveRowPresence<E> & LiveRowPublish<E> {
    const topics = new Map<string, LiveStream<E>>();
    return {
      name,
      connection: this,
      subscribe: (topic: LiveTopic, handlers: LiveHandlers<E>) =>
        this.subscribe(name, handlers, String(topic)),
      join: (topic: LiveTopic, handlers: LiveJoinHandlers<E> = {}) =>
        this.join<E>(name, String(topic), handlers),
      publish: (topic: LiveTopic, value: LiveValue<E>) => this.publishOn(name, String(topic), value),
      topic: (topic: LiveTopic) => {
        const key = String(topic);
        let stream = topics.get(key);
        if (!stream) {
          stream = {
            name,
            connection: this,
            subscribe: (handlers: LiveHandlers<E>) => this.subscribe(name, handlers, key),
          };
          topics.set(key, stream);
        }
        return stream;
      },
    };
  }

  /** The accessor for the stream called `name`, of the changes to `table`, whose primary key is `key`. */
  changesStream<Sch extends TableSchema, Key = LiveTopic>(
    name: string,
    table: string,
    key: string,
  ): LiveChangesStream<Sch, Key> {
    return {
      name,
      table,
      key,
      connection: this,
      subscribe: (query, handlers) => {
        const where = query.where === undefined ? undefined : whereObject(query.where);
        return this.subscribe(name, handlers, undefined, where);
      },
    };
  }

  /** The accessor for the `document` stream called `name`, whose root is `root` of kind `rootKind`. */
  documentStream<K extends "text" | "xml">(name: string, root: string, rootKind: K): LiveDocumentStream<K> {
    return {
      name,
      connection: this,
      root,
      rootKind,
      connect: <S = unknown>(topic: LiveTopic, handlers: LiveDocumentHandlers<S>) =>
        this.openDocument<S>(name, String(topic), handlers),
    };
  }

  /** Open `topic`'s document on `stream`: a subscription that keeps its members and carries its edits. */
  openDocument<S = unknown>(
    stream: string,
    topic: string,
    handlers: LiveDocumentHandlers<S>,
  ): LiveDocumentSession<S> {
    const { sub, subscription } = this.add(
      stream,
      {
        element: () => undefined,
        ready: handlers.ready,
        resync: handlers.resync,
        status: handlers.status,
        error: handlers.error,
        presence: (members: LiveMember[]) => handlers.presence?.(members as LiveMember<S>[]),
        docSync: (update: string, readOnly: boolean) => handlers.sync(update, readOnly),
        docUpdate: (update: string) => handlers.update(update),
      },
      topic,
      undefined,
    );
    const entry = () => this.entries.get(sub);
    return {
      get members() {
        return (entry()?.members ?? []) as LiveMember<S>[];
      },
      get me() {
        return entry()?.me;
      },
      get readOnly() {
        return entry()?.readOnly ?? true;
      },
      send: (update: string) => this.sendDocUpdate(sub, update),
      setState: (state: S) => this.setState(sub, state),
      close: () => subscription.close(),
    };
  }

  /**
   * Open the application's stream query `query` with `params` (TODO F7): the
   * query decides which stream and row this page is attached to, and whether
   * it may write there; `ready.opened` says what it opened.
   */
  openQuery<S = unknown>(
    query: string,
    params: Record<string, unknown>,
    handlers: LiveOpenHandlers<S>,
  ): LiveOpenedSession<S> {
    const { sub, subscription } = this.add(
      "",
      {
        element: (envelope: unknown) => handlers.element?.(envelope as LiveEnvelope<unknown>),
        echo: handlers.echo,
        ready: (info: LiveReady) => handlers.ready?.(info as LiveReady & { opened: LiveOpened }),
        resync: handlers.resync,
        status: handlers.status,
        lagged: handlers.lagged,
        error: handlers.error,
        presence: (members: LiveMember[]) => handlers.presence?.(members as LiveMember<S>[]),
        docSync: (update: string, readOnly: boolean) => handlers.sync?.(update, readOnly),
        docUpdate: (update: string) => handlers.update?.(update),
      },
      undefined,
      undefined,
      { name: query, params },
    );
    const entry = () => this.entries.get(sub);
    return {
      get opened() {
        return entry()?.opened;
      },
      get members() {
        return (entry()?.members ?? []) as LiveMember<S>[];
      },
      get me() {
        return entry()?.me;
      },
      get readOnly() {
        return entry()?.readOnly ?? true;
      },
      get canPublish() {
        return entry()?.canPublish ?? false;
      },
      send: (update: string) => this.sendDocUpdate(sub, update),
      publish: (value: unknown) => this.publish(sub, value),
      setState: (state: S) => this.setState(sub, state),
      close: () => subscription.close(),
    };
  }

  /** Send an edit on the document subscription `sub`, if it is ready and may edit; `false` when it was not sent. */
  sendDocUpdate(sub: string, update: string): boolean {
    const entry = this.entries.get(sub);
    if (!entry || !entry.ready || entry.readOnly || !this.socket || this.socket.readyState !== 1) {
      return false;
    }
    this.send({ type: "doc_update", sub, update });
    return true;
  }

  /**
   * Subscribe to `stream` (on `topic`, for a row stream; with `filter`, the
   * filter object, for a stream of changes), opening the socket if this is the
   * first subscription.
   */
  subscribe<E>(
    stream: string,
    handlers: LiveHandlers<E>,
    topic?: string,
    filter?: Record<string, unknown>,
  ): LiveSubscription {
    return this.add(stream, handlers as LiveHandlers<unknown>, topic, filter).subscription;
  }

  /**
   * Join `topic` of `stream` (none for a stream with one topic): a
   * subscription that also keeps the topic's members, and through which this
   * page sets its state and publishes.
   */
  join<E, S = unknown>(
    stream: string,
    topic: string | undefined,
    handlers: LiveJoinHandlers<E, S>,
  ): LiveRoom<LiveValue<E>, S> {
    const { sub, subscription } = this.add(
      stream,
      {
        ...(handlers as LiveJoinHandlers<unknown>),
        element: (envelope: unknown) => handlers.element?.(envelope as E),
        presence: (members: LiveMember[]) => handlers.presence?.(members as LiveMember<S>[]),
      },
      topic,
      undefined,
    );
    const entry = () => this.entries.get(sub);
    return {
      get members() {
        return (entry()?.members ?? []) as LiveMember<S>[];
      },
      get me() {
        return entry()?.me;
      },
      get canPublish() {
        return entry()?.canPublish ?? false;
      },
      setState: (state: S) => this.setState(sub, state),
      publish: (value: LiveValue<E>) => this.publish(sub, value),
      leave: () => subscription.close(),
    };
  }

  /** Publish `value` on the subscription `sub`, once it is `ready`. */
  publish(sub: string, value: unknown): void {
    const entry = this.entries.get(sub);
    if (!entry) return;
    if (entry.ready && this.socket && this.socket.readyState === 1) {
      this.send({ type: "publish", sub, value });
    } else {
      entry.outbox.push(value);
    }
  }

  /**
   * Publish `value` on `topic` of `stream`: on a subscription this page
   * already holds to it, or on one opened for the purpose and closed once the
   * value is sent.
   */
  publishOn(stream: string, topic: string | undefined, value: unknown): void {
    for (const [sub, entry] of this.entries) {
      if (entry.stream === stream && entry.topic === topic && entry.filter === undefined && entry.query === undefined) {
        this.publish(sub, value);
        return;
      }
    }
    let done = false;
    const once = this.add(
      stream,
      {
        element: () => undefined,
        ready: () => {
          if (done) return;
          done = true;
          this.publish(once.sub, value);
          once.subscription.close();
        },
        error: () => {
          done = true;
        },
      },
      topic,
      undefined,
    );
  }

  /** Set this page's presence state on `sub`, sent at most every `presenceInterval` ms (the latest wins). */
  setState(sub: string, state: unknown): void {
    const entry = this.entries.get(sub);
    if (!entry) return;
    entry.state = { value: state };
    // This page's own entry in the list changes at once, for its own render.
    if (entry.me !== undefined) {
      entry.members = entry.members.map((m) => (m.connection === entry.me ? { ...m, state } : m));
      entry.handlers.presence?.(entry.members);
    }
    this.flushState(sub);
  }

  private flushState(sub: string): void {
    const entry = this.entries.get(sub);
    if (!entry || entry.state === undefined || entry.stateTimer !== undefined) return;
    if (!entry.ready || !this.socket || this.socket.readyState !== 1) return;
    const interval = this.options.presenceInterval ?? 60;
    const wait = entry.stateSentAt + interval - Date.now();
    if (wait > 0) {
      entry.stateTimer = setTimeout(() => {
        entry.stateTimer = undefined;
        this.flushState(sub);
      }, wait);
      return;
    }
    entry.stateSentAt = Date.now();
    this.send({ type: "presence", sub, state: entry.state.value });
  }

  private add(
    stream: string,
    handlers: LiveHandlers<unknown>,
    topic: string | undefined,
    filter: Record<string, unknown> | undefined,
    query?: { name: string; params: Record<string, unknown> },
  ): { sub: string; subscription: LiveSubscription } {
    const sub = `s${this.nextSub++}`;
    const entry: LiveEntry = {
      stream,
      topic,
      filter,
      handlers,
      ready: false,
      canPublish: false,
      members: [],
      me: undefined,
      state: undefined,
      stateSentAt: 0,
      stateTimer: undefined,
      outbox: [],
      readOnly: true,
      query,
      opened: undefined,
    };
    this.entries.set(sub, entry);
    if (this.socket && this.socket.readyState === 1) {
      this.send(subscribeFrame(sub, entry));
    } else {
      this.open();
    }
    let active = true;
    return {
      sub,
      subscription: {
        close: () => {
          if (!active) return;
          active = false;
          const gone = this.entries.get(sub);
          if (gone?.stateTimer !== undefined) clearTimeout(gone.stateTimer);
          if (this.entries.delete(sub) && this.socket && this.socket.readyState === 1) {
            this.send({ type: "unsubscribe", sub });
          }
          if (this.entries.size === 0) this.shutdown();
        },
      },
    };
  }

  /** End every subscription and close the socket. */
  close(): void {
    this.entries.clear();
    this.shutdown();
  }

  private setStatus(status: LiveStatus): void {
    if (status === this.current) return;
    this.current = status;
    this.listeners.forEach((listener) => listener(status));
  }

  private send(frame: Record<string, unknown>): void {
    this.socket?.send(JSON.stringify(frame));
  }

  private open(): void {
    if (this.socket || this.timer !== undefined) return;
    const Socket = this.options.WebSocket ?? (typeof WebSocket === "undefined" ? undefined : WebSocket);
    if (!Socket) throw new Error("live updates need a WebSocket implementation (LiveOptions.WebSocket)");
    const socket = new Socket(this.url);
    this.socket = socket;
    socket.onopen = () => {
      const reconnect = this.opened;
      this.opened = true;
      this.attempt = 0;
      this.setStatus("open");
      this.entries.forEach((entry, sub) => {
        entry.ready = false;
        // A document waits for its next `doc_sync` before it edits again.
        entry.readOnly = true;
        if (entry.stateTimer !== undefined) {
          clearTimeout(entry.stateTimer);
          entry.stateTimer = undefined;
        }
        entry.stateSentAt = 0;
        this.send(subscribeFrame(sub, entry));
        if (reconnect) entry.handlers.resync?.();
      });
    };
    socket.onmessage = (event: MessageEvent) => this.receive(event.data);
    socket.onclose = () => {
      if (this.socket !== socket) return;
      this.socket = undefined;
      if (this.entries.size === 0) return;
      this.setStatus("reconnecting");
      const min = this.options.minDelay ?? 500;
      const max = this.options.maxDelay ?? 30000;
      const delay = Math.min(max, min * 2 ** this.attempt);
      this.attempt += 1;
      // Half the delay, plus up to half again at random: a server that restarts
      // is not met by every page reconnecting in the same millisecond.
      this.timer = setTimeout(() => {
        this.timer = undefined;
        this.open();
      }, delay / 2 + Math.random() * (delay / 2));
    };
  }

  private shutdown(): void {
    if (this.timer !== undefined) {
      clearTimeout(this.timer);
      this.timer = undefined;
    }
    const socket = this.socket;
    this.socket = undefined;
    this.opened = false;
    this.attempt = 0;
    socket?.close();
    this.setStatus("connecting");
  }

  private receive(data: unknown): void {
    let frame: Record<string, unknown>;
    try {
      const parsed: unknown = JSON.parse(String(data));
      if (!parsed || typeof parsed !== "object") return;
      frame = parsed as Record<string, unknown>;
    } catch {
      return;
    }
    const sub = typeof frame["sub"] === "string" ? frame["sub"] : undefined;
    const entry = sub === undefined ? undefined : this.entries.get(sub);
    switch (frame["type"]) {
      case "ready":
        if (entry && sub !== undefined) {
          entry.ready = true;
          entry.canPublish = frame["can_publish"] === true;
          if (frame["opened"] && typeof frame["opened"] === "object") {
            entry.opened = frame["opened"] as LiveOpened;
            entry.stream = entry.opened.stream;
          }
          entry.handlers.ready?.(frame as unknown as LiveReady);
          for (const value of entry.outbox.splice(0)) this.publish(sub, value);
        }
        break;
      case "presence":
      case "presence_diff":
        if (entry && sub !== undefined) {
          if (frame["type"] === "presence" && typeof frame["connection"] === "string") {
            entry.me = frame["connection"];
          }
          entry.members = applyPresence(entry.members, frame);
          // A list that does not carry the state this page set — the first
          // one after a reconnect — is told it again.
          const own = entry.state;
          const mine = entry.members.find((m) => m.connection === entry.me);
          if (own !== undefined && mine && JSON.stringify(mine.state) !== JSON.stringify(own.value)) {
            entry.members = entry.members.map((m) => (m === mine ? { ...m, state: own.value } : m));
            this.flushState(sub);
          }
          entry.handlers.presence?.(entry.members);
        }
        break;
      case "element":
        entry?.handlers.element(frame["envelope"]);
        break;
      case "doc_sync":
        if (entry && typeof frame["update"] === "string") {
          entry.readOnly = frame["read_only"] !== false;
          entry.handlers.docSync?.(frame["update"], entry.readOnly);
        }
        break;
      case "doc_update":
        if (entry && typeof frame["update"] === "string") entry.handlers.docUpdate?.(frame["update"]);
        break;
      case "lagged":
        entry?.handlers.lagged?.(Number(frame["dropped"] ?? 0));
        break;
      case "status":
        entry?.handlers.status?.(frame["status"]);
        break;
      case "revoked":
        if (entry && sub !== undefined) {
          this.entries.delete(sub);
          entry.handlers.error?.({ code: "revoked", message: "access to this stream ended" });
        }
        break;
      case "error": {
        const error: LiveError = {
          code: String(frame["code"] ?? "error"),
          message: String(frame["message"] ?? ""),
        };
        if (sub === undefined) {
          // About the connection, not one subscription: everyone hears it, and
          // the reconnect that follows a close asks again.
          this.entries.forEach((each) => each.handlers.error?.(error));
        } else if (entry) {
          // Refused before `ready`: the subscription never started, so it ends.
          if (!entry.ready) this.entries.delete(sub);
          entry.handlers.error?.(error);
        }
        break;
      }
      default:
        // A frame this client was generated before: ignored, never thrown on.
        break;
    }
  }
}

// --- live rows --------------------------------------------------------------

/**
 * One change to a table's rows, as one subscriber is sent it. `insert`,
 * `update` and `enter` (a row came into this subscriber's view) carry the row
 * unless the stream sends keys only; `leave` (a row left the view) and `delete`
 * never do.
 */
export type LiveChange<Row, Key = LiveTopic> =
  | { op: "insert" | "update" | "enter"; key: Key; row?: Row }
  | { op: "leave" | "delete"; key: Key; row?: undefined };

/** An element of a stream in its envelope, its `value` typed `V`. */
export type LiveEnvelope<V> = {
  stream: string;
  /** The topic it was published on, for a stream with topics. */
  topic?: string;
  value: V;
  /** When *this server* saw it — not a claim about when it was produced. */
  received_at: string;
  source?: unknown;
};

/** Which rows a subscription to a table's changes is about: the REST read's own filters. */
export type LiveChangesQuery<Row> = { where?: Filters<Row> };

/** A stream of a table's changes: subscribe with the filter a read of the table would use. */
export interface LiveChangesStream<Sch extends TableSchema, Key = LiveTopic> {
  readonly name: string;
  readonly connection: LiveConnection;
  /** The table whose changes these are. */
  readonly table: string;
  /** Its primary key's column, which every change's `key` is a value of. */
  readonly key: string;
  subscribe(
    query: LiveChangesQuery<Sch["row"]>,
    handlers: LiveHandlers<LiveEnvelope<LiveChange<Sch["row"], Key>>>,
  ): LiveSubscription;
}

/**
 * A REST read's `Filters` as the socket's filter object: `{ board: "eq.7" }`
 * is `{ board: { eq: "7" } }`, `in.(1,2)` a list, `is_null.true` a boolean —
 * the same lowering the server gives a query string, so a read and a
 * subscription with one filter are about the same rows.
 */
export function whereObject(filters: { readonly [column: string]: string | undefined }): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [column, spec] of Object.entries(filters)) {
    if (spec === undefined) continue;
    const dot = spec.indexOf(".");
    if (dot < 0) {
      throw new Error(`\`${column}: "${spec}"\` is not a filter: a filter is "op.value", e.g. "eq.${spec}"`);
    }
    const op = spec.slice(0, dot);
    out[column] = { [op]: filterOperand(op, spec.slice(dot + 1)) };
  }
  return out;
}

/** One operand as the server reads it: text, except a list for `in`/`nin` and a boolean for `is_null`. */
export function filterOperand(op: string, operand: string): unknown {
  if (op === "in" || op === "nin") {
    if (!operand.startsWith("(") || !operand.endsWith(")")) return operand;
    const items: string[] = [];
    let current = "";
    let quoted = false;
    for (const c of operand.slice(1, -1)) {
      if (c === '"') quoted = !quoted;
      else if (c === "," && !quoted) {
        items.push(current);
        current = "";
      } else current += c;
    }
    if (current !== "" || items.length > 0) items.push(current);
    return items;
  }
  if (op === "is_null") return operand === "true" ? true : operand === "false" ? false : operand;
  return operand;
}

/** How a read's rows are kept: by which key, in which order, cut to which columns. */
export interface LiveRowsPlan {
  /** The primary key's column. */
  key: string;
  /** The order the rows are kept in, most significant first. */
  order: Array<{ column: string; desc: boolean }>;
  /** The columns a change's row is cut to, or `undefined` for whole rows. */
  columns: string[] | undefined;
  /** Whether a change's row cannot stand in for a read, so changed rows are read again. */
  refetch: boolean;
  /** The `select` the read is made with: the caller's, plus the key and order columns it needs. */
  select: string | undefined;
}

/** The top-level items of a `select`: split on the commas outside any `(…)`. */
function selectItems(select: string): string[] {
  const items: string[] = [];
  let depth = 0;
  let current = "";
  for (const c of select) {
    if (c === "(") depth += 1;
    if (c === ")") depth = Math.max(0, depth - 1);
    if (c === "," && depth === 0) {
      items.push(current.trim());
      current = "";
    } else current += c;
  }
  items.push(current.trim());
  return items.filter((item) => item !== "");
}

/** Plan how the rows of a read with `orderBy` and `select` are kept, by the key column `key`. */
export function liveRowsPlan(key: string, options: { orderBy?: string; select?: string } = {}): LiveRowsPlan {
  const order = (options.orderBy ?? "")
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item !== "")
    .map((item) => {
      const [column, direction] = item.split(".");
      return { column: column ?? item, desc: direction === "desc" };
    });
  const items = selectItems(options.select ?? "");
  if (items.length === 0) return { key, order, columns: undefined, refetch: false, select: undefined };
  // An embed or an alias answers something other than the table's row: the
  // stream's row cannot stand in for it.
  const refetch = items.some((item) => item.includes("(") || item.includes(":"));
  const needed = [key, ...order.map((o) => o.column)].filter((column) => !items.includes(column));
  const all = [...items, ...needed.filter((column, i) => needed.indexOf(column) === i)];
  return { key, order, columns: refetch ? undefined : all, refetch, select: all.join(",") };
}

/** Two column values in an order's sense: nulls last (ascending), numbers as numbers, text by code unit. */
export function compareValues(a: unknown, b: unknown): number {
  const aNull = a === null || a === undefined;
  const bNull = b === null || b === undefined;
  if (aNull || bNull) return aNull === bNull ? 0 : aNull ? 1 : -1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  if (typeof a === "boolean" && typeof b === "boolean") return Number(a) - Number(b);
  const x = typeof a === "string" ? a : JSON.stringify(a);
  const y = typeof b === "string" ? b : JSON.stringify(b);
  return x < y ? -1 : x > y ? 1 : 0;
}

/** `rows` in the plan's order — a stable sort, so ties keep the order they had. */
export function sortLiveRows<R>(rows: readonly R[], plan: LiveRowsPlan): R[] {
  if (plan.order.length === 0) return [...rows];
  return [...rows].sort((a, b) => {
    for (const { column, desc } of plan.order) {
      const c = compareValues((a as Record<string, unknown>)[column], (b as Record<string, unknown>)[column]);
      if (c !== 0) return desc ? -c : c;
    }
    return 0;
  });
}

/** A row's key, as text: `7` and `"7"` are the same row. */
function rowKey(row: unknown, plan: LiveRowsPlan): string {
  return String((row as Record<string, unknown>)[plan.key]);
}

/** A change's row cut to the plan's columns. */
function cutRow(row: object, plan: LiveRowsPlan): object {
  if (plan.columns === undefined) return row;
  const out: Record<string, unknown> = {};
  for (const column of plan.columns) out[column] = (row as Record<string, unknown>)[column];
  return out;
}

/** `rows` with `row` put in place of the row with its key, or added, and in order. */
function upsertRow<R>(rows: readonly R[], row: R, plan: LiveRowsPlan): R[] {
  const key = rowKey(row, plan);
  const at = rows.findIndex((each) => rowKey(each, plan) === key);
  const next = [...rows];
  if (at >= 0) next[at] = row;
  else next.push(row);
  return sortLiveRows(next, plan);
}

/** What applying one change does: the rows after it, and a key to read again if the change could not say. */
export interface LiveRowsStep<R> {
  rows: R[];
  refetch?: unknown;
}

/**
 * Apply one change to a read's rows. `leave` and `delete` take the row out;
 * `insert`, `update` and `enter` put it in, in order — or, when the change has
 * no row or its row is not what the read answers, leave the rows as they are
 * and name the key to read again.
 */
export function applyLiveChange<R>(
  rows: readonly R[],
  change: LiveChange<unknown, unknown>,
  plan: LiveRowsPlan,
): LiveRowsStep<R> {
  const key = String(change.key);
  switch (change.op) {
    case "leave":
    case "delete":
      return { rows: rows.filter((row) => rowKey(row, plan) !== key) };
    case "insert":
    case "update":
    case "enter":
      if (change.row === undefined || change.row === null || plan.refetch) {
        return { rows: [...rows], refetch: change.key };
      }
      return { rows: upsertRow(rows, cutRow(change.row as object, plan) as R, plan) };
    default:
      // An op this client was generated before: read the row again rather than guess.
      return { rows: [...rows], refetch: (change as { key: unknown }).key };
  }
}

/**
 * The rows a read of `keys` answered, merged into `rows`: each key the read
 * answered is put in place, and each it did not — deleted, or no longer
 * readable — is taken out.
 */
export function mergeLiveRows<R>(
  rows: readonly R[],
  keys: readonly unknown[],
  read: readonly R[],
  plan: LiveRowsPlan,
): R[] {
  const answered = new Map(read.map((row) => [rowKey(row, plan), row]));
  let next = [...rows];
  for (const key of keys.map(String)) {
    const row = answered.get(key);
    next = row === undefined ? next.filter((each) => rowKey(each, plan) !== key) : upsertRow(next, row, plan);
  }
  return next;
}

/** An `in.(…)` list item, quoted when it holds a comma or a quote of its own. */
function listItem(key: unknown): string {
  const text = String(key);
  return /[,"()]/.test(text) ? `"${text.replace(/"/g, "")}"` : text;
}

/** How rows are read and kept live: the read's filter, order and `select`. */
export type LiveRowsOptions<Row, S extends string = ""> = {
  /** The read's filters, and the subscription's — one value for both. */
  where?: Filters<Row>;
  orderBy?: Order<Row>;
  select?: S;
};

/** A table the client reads and whose changes the application exposes: what `LiveRows` needs. */
export interface LiveTable<Sch extends TableSchema = TableSchema, Key = LiveTopic> {
  list(query?: { select?: string; filter?: Filters<Sch["row"]>; order?: Order<Sch["row"]> }): Promise<unknown[]>;
  readonly changes: LiveChangesStream<Sch, Key>;
}

/** What `LiveRows` holds: the rows, whether a read is in flight, and the last failure. */
export interface LiveRowsState<R> {
  rows: R[];
  /** A full read is in flight (the first, or one after a reconnect or a lag). */
  loading: boolean;
  /** A read that failed, or the server refusing the subscription. */
  error: Error | LiveError | undefined;
}

/**
 * A read of a table kept current by its changes: reads once the subscription
 * is ready, applies each change, and reads again after a reconnect or a lag.
 * `current` is a new object after every change and the same object between
 * them, so it can back `useSyncExternalStore` as it stands.
 */
export class LiveRows<R> {
  private state: LiveRowsState<R> = { rows: [], loading: true, error: undefined };
  private readonly listeners = new Set<() => void>();
  private subscription: LiveSubscription | undefined;
  private generation = 0;
  private reading = false;
  private waiting: Array<LiveChange<unknown, unknown>> = [];
  private readonly versions = new Map<string, number>();
  private readonly pending = new Map<string, unknown>();
  private scheduled = false;
  private readonly table: LiveTable<TableSchema, unknown>;
  private readonly options: LiveRowsOptions<object, string>;
  readonly plan: LiveRowsPlan;

  constructor(table: LiveTable<TableSchema, unknown>, options: LiveRowsOptions<object, string> = {}) {
    this.table = table;
    this.options = options;
    this.plan = liveRowsPlan(table.changes.key, {
      orderBy: options.orderBy as string | undefined,
      select: options.select,
    });
  }

  /** The rows as they are now. */
  get current(): LiveRowsState<R> {
    return this.state;
  }

  /** Be told after every change to `current`. Returns the function that stops it. */
  onChange(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /** Subscribe, and read once the subscription is ready. Starting again after `close` is allowed. */
  start(): void {
    if (this.subscription) return;
    this.subscription = this.table.changes.subscribe(
      { where: this.options.where },
      {
        // The first `ready`, and the one after every reconnect (`resync`):
        // what arrived while the socket was down is gone, so read it all again.
        ready: () => this.refresh(),
        element: (envelope) => this.receive(envelope.value),
        lagged: () => this.refresh(),
        error: (error) => this.set({ ...this.state, loading: false, error }),
      },
    );
  }

  /** Stop following the table. */
  close(): void {
    this.generation += 1;
    this.reading = false;
    this.waiting = [];
    this.pending.clear();
    this.subscription?.close();
    this.subscription = undefined;
  }

  /** Read every row again; changes that arrive meanwhile are applied on top. */
  refresh(): void {
    const generation = ++this.generation;
    this.reading = true;
    this.waiting = [];
    this.pending.clear();
    if (!this.state.loading) this.set({ ...this.state, loading: true });
    this.table
      .list({ select: this.plan.select, filter: this.options.where, order: this.options.orderBy })
      .then(
        (rows) => {
          if (generation !== this.generation) return;
          this.reading = false;
          let next = rows as R[];
          const waiting = this.waiting;
          this.waiting = [];
          for (const change of waiting) next = this.step(next, change);
          this.set({ rows: next, loading: false, error: undefined });
        },
        (error: unknown) => {
          if (generation !== this.generation) return;
          this.reading = false;
          this.set({ ...this.state, loading: false, error: error instanceof Error ? error : new Error(String(error)) });
        },
      );
  }

  private set(state: LiveRowsState<R>): void {
    this.state = state;
    this.listeners.forEach((listener) => listener());
  }

  private receive(change: LiveChange<unknown, unknown>): void {
    if (this.reading) {
      this.waiting.push(change);
      return;
    }
    this.set({ ...this.state, rows: this.step(this.state.rows, change) });
  }

  /** Apply one change, counting it against its key and asking for the key again if the change could not say. */
  private step(rows: R[], change: LiveChange<unknown, unknown>): R[] {
    const key = String(change.key);
    this.versions.set(key, (this.versions.get(key) ?? 0) + 1);
    const step = applyLiveChange<R>(rows, change, this.plan);
    if (step.refetch !== undefined) this.schedule(step.refetch);
    return step.rows;
  }

  private schedule(key: unknown): void {
    this.pending.set(String(key), key);
    if (this.scheduled) return;
    this.scheduled = true;
    queueMicrotask(() => {
      this.scheduled = false;
      this.readKeys();
    });
  }

  /** Read the keys changes could not say enough about, in one read. */
  private readKeys(): void {
    const keys = Array.from(this.pending.values());
    this.pending.clear();
    if (keys.length === 0) return;
    const generation = this.generation;
    const asked = new Map(keys.map((key) => [String(key), this.versions.get(String(key)) ?? 0]));
    const filter = { [this.plan.key]: `in.(${keys.map(listItem).join(",")})` } as Filters<object>;
    this.table.list({ select: this.plan.select, filter }).then(
      (rows) => {
        if (generation !== this.generation) return;
        // A key a newer change has moved on from is that change's to settle.
        const current = keys.filter((key) => (this.versions.get(String(key)) ?? 0) === asked.get(String(key)));
        this.set({ ...this.state, rows: mergeLiveRows(this.state.rows, current, rows as R[], this.plan) });
      },
      (error: unknown) => {
        if (generation !== this.generation) return;
        this.set({ ...this.state, error: error instanceof Error ? error : new Error(String(error)) });
      },
    );
  }
}


/** How {@link upload} sends a file. */
export interface UploadOptions {
  /** Called after each chunk: bytes the server has, and the file's size. */
  onProgress?: (sent: number, total: number) => void;
  /** Stops the upload (it stays resumable) and rejects with an `AbortError`. */
  signal?: AbortSignal;
  /** Failed chunks in a row to retry before giving up (default 5). */
  retries?: number;
  /** Bytes per `PATCH` (default 5 MiB). */
  chunkSize?: number;
  /** The name to upload under, when the `Blob` is not a `File` with one. */
  filename?: string;
}

/** A finished upload: where the file is in its store, and the URL it is served
 * at (null when no route of the application serves it). */
export interface UploadResult {
  path: string;
  url: string | null;
}

const TUS_VERSION = "1.0.0";

function uploadAborted(): Error {
  const e = new Error("the upload was stopped");
  e.name = "AbortError";
  return e;
}

/** UTF-8, then base64 — what tus metadata values are. */
function tusValue(value: string): string {
  const bytes = new TextEncoder().encode(value);
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
}

function rememberUpload(key: string, location: string | null): void {
  try {
    if (typeof localStorage === "undefined") return;
    if (location === null) localStorage.removeItem(key);
    else localStorage.setItem(key, location);
  } catch {
    // No storage (a private window, a native app): only resuming after a
    // reload is lost.
  }
}

function rememberedUpload(key: string): string | null {
  try {
    return typeof localStorage === "undefined" ? null : localStorage.getItem(key);
  } catch {
    return null;
  }
}

/** `location` against the URL it answered, so a relative `Location` works for
 * a client with an absolute `baseUrl`. */
function resolveLocation(location: string, from: string): string {
  if (/^https?:\/\//.test(location) || !location.startsWith("/")) return location;
  const origin = /^(https?:\/\/[^/]+)/.exec(from);
  return origin ? origin[1] + location : location;
}

function pause(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(uploadAborted());
    const timer = setTimeout(resolve, ms);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(uploadAborted());
    }, { once: true });
  });
}

/** Upload `file` to the upload slot whose create URL is `slotUrl`, resuming
 * after dropped connections and reloads. What `api.uploads.<slot>` calls. */
export async function upload(
  fetchImpl: typeof fetch,
  slotUrl: string,
  file: Blob,
  options: UploadOptions = {},
): Promise<UploadResult> {
  const total = file.size;
  const chunkSize = Math.max(1, options.chunkSize ?? 5 * 1024 * 1024);
  const retries = Math.max(0, options.retries ?? 5);
  const signal = options.signal;
  const named = file as Blob & { name?: string; lastModified?: number };
  const filename = options.filename ?? named.name ?? "upload";
  const fingerprint = `feldspar-upload:${slotUrl}:${filename}:${total}:${named.lastModified ?? ""}`;
  const headers = (method: string, extra: Record<string, string> = {}) => ({
    ...requestHeaders(method, false),
    "tus-resumable": TUS_VERSION,
    ...extra,
  });
  if (signal?.aborted) throw uploadAborted();

  // What the server has of an upload, or null when it no longer knows it.
  const offsetOf = async (location: string): Promise<number | null> => {
    const res = await fetchImpl(location, { method: "HEAD", headers: headers("HEAD"), signal });
    if (!res.ok) return null;
    const offset = Number(res.headers.get("upload-offset"));
    return Number.isFinite(offset) ? offset : null;
  };

  let location = rememberedUpload(fingerprint);
  let offset = 0;
  if (location !== null) {
    const known = await offsetOf(location).catch((e: unknown) => {
      if (signal?.aborted) throw uploadAborted();
      throw e;
    });
    if (known === null) location = null;
    else offset = known;
  }
  if (location === null) {
    const res = await fetchImpl(slotUrl, {
      method: "POST",
      headers: headers("POST", {
        "upload-length": String(total),
        "upload-metadata": `filename ${tusValue(filename)},filetype ${tusValue(file.type || "application/octet-stream")}`,
      }),
      signal,
    });
    if (res.status !== 201) throw await clientError("upload", res);
    const given = res.headers.get("location");
    if (!given) throw new Error("upload failed: the server named no upload URL");
    location = resolveLocation(given, slotUrl);
    rememberUpload(fingerprint, location);
  }
  options.onProgress?.(offset, total);

  let failures = 0;
  for (;;) {
    if (signal?.aborted) throw uploadAborted();
    const end = Math.min(offset + chunkSize, total);
    let res: Response | null = null;
    try {
      res = await fetchImpl(location, {
        method: "PATCH",
        headers: headers("PATCH", {
          "upload-offset": String(offset),
          "content-type": "application/offset+octet-stream",
        }),
        body: file.slice(offset, end),
        signal,
      });
    } catch {
      if (signal?.aborted) throw uploadAborted();
      res = null;
    }
    if (res !== null && res.ok) {
      failures = 0;
      const now = Number(res.headers.get("upload-offset"));
      offset = Number.isFinite(now) ? now : end;
      options.onProgress?.(offset, total);
      if (offset >= total) {
        rememberUpload(fingerprint, null);
        return {
          path: res.headers.get("feldspar-file-path") ?? "",
          url: res.headers.get("feldspar-file-url"),
        };
      }
      continue;
    }
    // A refusal that another try will not change: the slot, the size, the type.
    if (res !== null && res.status >= 400 && res.status < 500 && res.status !== 409 && res.status !== 423) {
      if (res.status === 404) rememberUpload(fingerprint, null);
      throw await clientError("upload", res);
    }
    failures += 1;
    if (failures > retries) {
      throw res === null
        ? new Error("upload failed: the connection kept dropping")
        : await clientError("upload", res);
    }
    await pause(Math.min(500 * 2 ** (failures - 1), 10_000), signal);
    // What arrived before the failure is kept: ask, and go on from there.
    const known = await offsetOf(location).catch(() => null);
    if (known !== null) offset = known;
  }
}

/** One piece of an agent's message, in the order it happened. A tool part's
 * `arguments` and `result` are present only where the application shows its
 * agent's tools in full. */
export type AgentPart =
  | { type: "text"; text: string }
  | { type: "reasoning"; text: string }
  | {
      type: "tool";
      id: string;
      name: string;
      state: "running" | "done" | "error";
      arguments?: unknown;
      result?: string;
    }
  | AgentDisplayPart
  | AgentAttachmentPart
  | { type: "request"; request: AgentRequest }
  | { type: "error"; text: string };

/** A file attached to a chat message, as it is sent: an image the model looks
 * at (PNG, JPEG, GIF or WebP, up to 5 MiB) or a text document it reads, such
 * as Markdown, plain text, CSV or JSON (up to 1 MiB). At most 10 per message.
 * `data` is the file's bytes in base64; make one from a `File` with
 * `agentAttachment(file)`. */
export interface AgentAttachment {
  name: string;
  media_type: string;
  data: string;
}

/** An attached file in a person's message. An image's `url` is a `data:` URL
 * an `<img>` can show; a document has none — the person has the file. */
export interface AgentAttachmentPart {
  type: "attachment";
  name: string;
  media_type: string;
  size: number;
  url?: string;
}

/** Something a tool showed the person and not the model: rows, an image or
 * audio. Fetch it with `runs.partUrl(run, id)` (an image's `src`) or
 * `runs.partRows(run, id)`. */
export interface AgentDisplayPart {
  type: "display";
  id: string;
  kind: "rows" | "image" | "audio";
  mime_type: string;
  summary: string;
}

/** One option of a question or a select. */
export interface AgentOption {
  value: string;
  label?: string;
  description?: string;
}

/** A question the agent is waiting on. Answer it with `answer(request.id,
 * value, { run })`: an option's value (a list of them when `multiple`), text,
 * or `true`/`false` to approve. */
export type AgentRequest = { id: string; prompt: string; tool_call: string; trait_key: string } & (
  | { kind: "choice"; options: AgentOption[]; multiple: boolean }
  | { kind: "text"; placeholder?: string }
  | { kind: "approve"; label: string; payload: unknown }
  | { kind: "button"; label: string; payload: unknown }
);

/** A control the agent adds to the chat's input row; its value is sent in
 * `controls`. */
export type AgentControl = { name: string; label: string } & (
  | { kind: "select"; options: AgentOption[]; default?: string }
  | { kind: "toggle"; default: boolean }
  | { kind: "button" }
  /** Choosing an option sends its value at once as the message. */
  | { kind: "send"; options: AgentOption[] }
);

/** A message of a conversation with an agent: what the person said, or
 * everything the agent did in answer to it. */
export interface AgentMessage {
  id: string;
  role: "user" | "assistant";
  parts: AgentPart[];
}

/** What a turn streams, in order: `run` first (so a new conversation can be
 * put in a history list at once), then deltas, tool calls and their results,
 * and `done` last. An `error` may arrive at any point before `done`. */
export type AgentEvent =
  | { type: "run"; run: string }
  | { type: "text"; delta: string }
  | { type: "reasoning"; delta: string }
  | { type: "tool_call"; id: string; name: string; arguments?: unknown }
  | { type: "tool_result"; id: string; name: string; content?: string; is_error: boolean }
  | { type: "display"; parts: AgentDisplayPart[] }
  | { type: "error"; message: string }
  | {
      type: "done";
      run: string | null;
      state: "done" | "failed" | "aborted" | "running" | "waiting";
      answer: string;
      conclusion?: "answered" | "max_steps" | "aborted" | "over_budget" | "stuck" | "awaiting_user";
      /** The question an `awaiting_user` turn ended on. */
      request?: AgentRequest;
    };

/** A conversation in a history list. */
export interface AgentRunSummary {
  id: string;
  title: string;
  state: string;
  created_at: string;
  updated_at: string;
}

/** A conversation with its transcript, and the question it waits on. */
export interface AgentRun extends AgentRunSummary {
  messages: AgentMessage[];
  awaiting: AgentRequest | null;
}

/** What a single prompt came to. */
export interface AgentAnswer {
  run: string;
  state: string;
  answer: string;
  conclusion: string | null;
  /** The tools it ran, as far as the application shows them. */
  tools: Array<{ name: string; is_error: boolean }>;
}

/** A value a prompt template's placeholder is filled with. */
export type AgentInputValue = string | number | boolean | Record<string, unknown> | unknown[];

/** How a chat turn is sent. */
export interface AgentChatOptions {
  /** The conversation to continue; a new one is started without it. */
  run?: string;
  /** Stops the turn. The server stops the agent, and the run is `aborted`. */
  signal?: AbortSignal;
  /** The values of the agent's composer controls (`controls()`). */
  controls?: Record<string, unknown>;
  /** Files sent with the message (`agentAttachment(file)`): images and text
   * documents the message can ask about. With attachments, the message may be
   * empty. */
  attachments?: AgentAttachment[];
}

/** Chat with an agent, and the history of the conversations. */
export interface AgentChatApi {
  /** One turn: send `message`, with any `options.attachments`, and iterate
   * over what the agent does in answer. */
  chat(message: string, options?: AgentChatOptions): AsyncGenerator<AgentEvent>;
  /** Answer the question conversation `options.run` waits on, as the next
   * turn. A question that is no longer waiting is refused. */
  answer(requestId: string, value: unknown, options: AgentChatOptions & { run: string }): AsyncGenerator<AgentEvent>;
  /** The controls the agent adds to the chat's input row. */
  controls(): Promise<AgentControl[]>;
  runs: {
    /** The caller's own conversations with this agent, newest first. */
    list(): Promise<AgentRunSummary[]>;
    /** One of them, with its transcript. */
    get(id: string): Promise<AgentRun>;
    /** Give one a title of the caller's choosing. */
    rename(id: string, title: string): Promise<AgentRunSummary>;
    delete(id: string): Promise<{ deleted: true }>;
    /** Where a display part's bytes are: an image's `src`, an audio's. */
    partUrl(run: string, part: string): string;
    /** A rows part: `{ title, view, columns, rows }`. */
    partRows(run: string, part: string): Promise<{ title: string | null; view: string | null; columns: string[]; rows: Record<string, unknown>[] }>;
  };
}

/** Send an agent a single prompt: `In` is free text, or the values of the
 * application's prompt template. */
export interface AgentPromptApi<In> {
  /** Ask, and wait for the answer. */
  prompt(input: In, options?: { signal?: AbortSignal }): Promise<AgentAnswer>;
  /** Ask, and iterate over what the agent does, as a chat turn streams it. */
  promptStream(input: In, options?: { signal?: AbortSignal }): AsyncGenerator<AgentEvent>;
}

/** A message the person is sending, to show before the agent answers: its
 * attachments, then its text — as a stored transcript reads it back. */
export function userMessage(text: string, attachments: AgentAttachment[] = []): AgentMessage {
  const parts: AgentPart[] = attachments.map(agentAttachmentPart);
  if (text !== "" || parts.length === 0) parts.push({ type: "text", text });
  return { id: `local-${Date.now()}-${Math.random().toString(36).slice(2)}`, role: "user", parts };
}

/** The image types an attachment may be; anything else is sent as text. */
const AGENT_IMAGE_TYPES = ["image/png", "image/jpeg", "image/gif", "image/webp"];

/** A file — from an `<input type="file">`, a drop or a paste — as an attachment
 * to send with `chat(message, { attachments })`. Refused, with the file's name,
 * when it is an image of another type, too large, or neither an image nor
 * UTF-8 text; the server checks the same again. */
export async function agentAttachment(file: Blob & { name?: string }): Promise<AgentAttachment> {
  const type = file.type.toLowerCase();
  const image = type.startsWith("image/");
  const name = file.name || (image ? "image" : "attachment");
  if (image && !AGENT_IMAGE_TYPES.includes(type === "image/jpg" ? "image/jpeg" : type)) {
    throw new Error(`${name}: only PNG, JPEG, GIF and WebP images can be attached`);
  }
  if (file.size > (image ? 5 : 1) * 1024 * 1024) {
    throw new Error(`${name}: an attached ${image ? "image may be at most 5" : "document may be at most 1"} MiB`);
  }
  const bytes = new Uint8Array(await file.arrayBuffer());
  if (!image) {
    try {
      new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    } catch {
      throw new Error(`${name}: only images and text documents can be attached`);
    }
  }
  let binary = "";
  for (let at = 0; at < bytes.length; at += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(at, at + 0x8000));
  }
  return { name, media_type: type, data: btoa(binary) };
}

/** An attachment as the part a transcript shows it as. */
export function agentAttachmentPart(attachment: AgentAttachment): AgentAttachmentPart {
  const padding = attachment.data.match(/=*$/)?.[0].length ?? 0;
  const size = Math.floor((attachment.data.length * 3) / 4) - padding;
  const part: AgentAttachmentPart = { type: "attachment", name: attachment.name, media_type: attachment.media_type, size };
  if (AGENT_IMAGE_TYPES.includes(attachment.media_type)) {
    part.url = `data:${attachment.media_type};base64,${attachment.data}`;
  }
  return part;
}

/** `messages` with `event` folded in: deltas extend the agent's last message
 * (starting one if the last message is the person's), a tool call adds a tool
 * part and its result settles it. `run` and `done` change no message — they
 * are the caller's to keep. A new array; the input is not changed. */
export function applyAgentEvent(messages: AgentMessage[], event: AgentEvent): AgentMessage[] {
  if (event.type === "run") return messages;
  if (event.type === "done" && !event.request) return messages;
  const out = messages.slice();
  let last = out[out.length - 1];
  if (!last || last.role !== "assistant") {
    last = { id: `local-${out.length}-${Date.now()}`, role: "assistant", parts: [] };
    out.push(last);
  } else {
    last = { ...last, parts: last.parts.slice() };
    out[out.length - 1] = last;
  }
  const parts = last.parts;
  const tail = parts[parts.length - 1];
  switch (event.type) {
    case "text":
    case "reasoning":
      if (tail && tail.type === event.type) {
        parts[parts.length - 1] = { type: event.type, text: tail.text + event.delta };
      } else {
        parts.push({ type: event.type, text: event.delta });
      }
      break;
    case "tool_call":
      parts.push({ type: "tool", id: event.id, name: event.name, state: "running", arguments: event.arguments });
      break;
    case "tool_result": {
      const at = parts.findIndex((p) => p.type === "tool" && p.id === event.id);
      const settled: AgentPart = {
        type: "tool",
        id: event.id,
        name: event.name,
        state: event.is_error ? "error" : "done",
        ...(at >= 0 && parts[at].type === "tool" && "arguments" in parts[at] ? { arguments: (parts[at] as { arguments?: unknown }).arguments } : {}),
        ...(event.content !== undefined ? { result: event.content } : {}),
      };
      if (at >= 0) parts[at] = settled;
      else parts.push(settled);
      break;
    }
    case "display":
      parts.push(...event.parts);
      break;
    case "done":
      // A turn that ended on a question: the question closes the message.
      if (event.request) parts.push({ type: "request", request: event.request });
      break;
    case "error":
      parts.push({ type: "error", text: event.message });
      break;
  }
  return out;
}

/** The events of a `text/event-stream` response, one `data:` JSON each. */
async function* agentEvents(op: string, res: Response): AsyncGenerator<AgentEvent> {
  if (!res.ok) throw await clientError(op, res);
  if (!res.body) return;
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let cut: number;
      while ((cut = buffer.indexOf("\n\n")) >= 0) {
        const frame = buffer.slice(0, cut);
        buffer = buffer.slice(cut + 2);
        const data = frame
          .split("\n")
          .filter((line) => line.startsWith("data:"))
          .map((line) => line.slice(5).trimStart())
          .join("\n");
        if (data) yield JSON.parse(data) as AgentEvent;
      }
    }
  } finally {
    reader.releaseLock();
  }
}

/** The calls of one exposed agent at `url` (`{mount}/_agents/{name}`). What
 * `api.agents["<name>"]` is. */
export function agentApi(doFetch: typeof fetch, url: string): AgentChatApi & AgentPromptApi<string | Record<string, AgentInputValue>> {
  const json = async <T>(op: string, method: string, path: string, body?: unknown): Promise<T> => {
    const res = await doFetch(`${url}${path}`, {
      method,
      headers: requestHeaders(method, body !== undefined),
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    if (!res.ok) throw await clientError(op, res);
    return (await res.json()) as T;
  };
  const stream = async function* (op: string, path: string, body: unknown, signal?: AbortSignal): AsyncGenerator<AgentEvent> {
    const headers = requestHeaders("POST", true);
    headers["accept"] = "text/event-stream";
    const res = await doFetch(`${url}${path}`, { method: "POST", headers, body: JSON.stringify(body), signal });
    yield* agentEvents(op, res);
  };
  const promptBody = (input: string | Record<string, AgentInputValue>) => (typeof input === "string" ? { prompt: input } : { input });
  return {
    chat(message, options = {}) {
      return stream(
        "chat",
        "/chat",
        { message, run: options.run, controls: options.controls, attachments: options.attachments },
        options.signal,
      );
    },
    answer(requestId, value, options) {
      return stream(
        "answer",
        "/chat",
        { answers_request: requestId, value, run: options.run, controls: options.controls },
        options.signal,
      );
    },
    controls: () => json<AgentControl[]>("controls", "GET", "/controls"),
    runs: {
      list: () => json<AgentRunSummary[]>("runs.list", "GET", "/runs"),
      get: (id) => json<AgentRun>("runs.get", "GET", `/runs/${encodeURIComponent(id)}`),
      rename: (id, title) => json<AgentRunSummary>("runs.rename", "PATCH", `/runs/${encodeURIComponent(id)}`, { title }),
      delete: (id) => json<{ deleted: true }>("runs.delete", "DELETE", `/runs/${encodeURIComponent(id)}`),
      partUrl: (run, part) => `${url}/runs/${encodeURIComponent(run)}/parts/${encodeURIComponent(part)}`,
      partRows: (run, part) =>
        json("runs.partRows", "GET", `/runs/${encodeURIComponent(run)}/parts/${encodeURIComponent(part)}`),
    },
    async prompt(input, options = {}) {
      const res = await doFetch(`${url}/prompt`, {
        method: "POST",
        headers: requestHeaders("POST", true),
        body: JSON.stringify(promptBody(input)),
        signal: options.signal,
      });
      if (!res.ok) throw await clientError("prompt", res);
      return (await res.json()) as AgentAnswer;
    },
    promptStream(input, options = {}) {
      return stream("prompt", "/prompt?stream=1", promptBody(input), options.signal);
    },
  };
}
